function init(){setupTabs(),setupThemeToggle(),setupBookmark(),setupTimeline(),setupJourneyIntegration()}function setupTabs(){const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-content");e.forEach(n=>{n.addEventListener("click",()=>{e.forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),t.forEach(e=>{e.classList.remove("active"),e.setAttribute("hidden","")}),n.classList.add("active"),n.setAttribute("aria-selected","true");const a=document.getElementById(n.dataset.tab);a.classList.add("active"),a.removeAttribute("hidden")})})}function setupThemeToggle(){const e=document.getElementById("theme-toggle");e.addEventListener("click",()=>{document.body.classList.toggle("light-theme"),localStorage.setItem("theme",document.body.classList.contains("light-theme")?"light":"dark"),e.textContent=document.body.classList.contains("light-theme")?"☀️":"🌙"}),"light"===localStorage.getItem("theme")&&(document.body.classList.add("light-theme"),e.textContent="☀️")}function setupBookmark(){const e=document.getElementById("bookmark-btn"),t="art-kalamkari",n=()=>{e.textContent=window.Journey&&window.Journey.isSaved(t)?"✅ Saved to Journey":"🔖 Bookmark to My Journey"};n(),e.addEventListener("click",()=>{window.Journey&&(window.Journey.toggle({id:t,explorerPage:"frontend/kalamkari-art-explorer/index.html",title:"Kalamkari Art",thumbnail:"https://placehold.co/100/059669/fff",category:"art"}),n())})}function setupTimeline(){const e=document.querySelectorAll(".timeline-step");e.forEach(t=>{t.addEventListener("click",()=>{const n=t.dataset.step;e.forEach(e=>e.classList.remove("active")),t.classList.add("active"),document.querySelectorAll(".timeline-detail").forEach(e=>e.classList.remove("active"));const a=document.getElementById(`detail-${n}`);a&&a.classList.add("active")})})}function setupJourneyIntegration(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("frontend/kalamkari-art-explorer/index.html",[{id:"art-kalamkari",title:"Kalamkari Art",description:"Hand-painted textile art from Andhra Pradesh.",link:"#"}])}document.addEventListener("DOMContentLoaded",init);